/// The extension IEs of `TraceActivation-ExtIEs` (NGAP-IEs). IEs not defined here are kept in `unknown_ies`.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct TraceActivationExtIes {
    /// `id-MDTConfiguration` (id 255, Ignore, Optional)
    pub mdt_configuration: Option<MdtConfiguration>,
    /// `id-TraceCollectionEntityURI` (id 257, Ignore, Optional)
    pub trace_collection_entity_uri: Option<UriAddress>,
    /// IEs this version of the specification does not define here, as received (id, criticality, encoded value).
    pub unknown_ies: Vec<rt::ie::RawIe>,
}

impl TraceActivationExtIes {
    /// A value with the mandatory IEs given and every optional one absent.
    pub fn new() -> Self {
        Self {
            mdt_configuration: None,
            trace_collection_entity_uri: None,
            unknown_ies: Vec::new(),
        }
    }
}

impl rt::AperEncode for TraceActivationExtIes {
    fn aper_encode(&self, w: &mut rt::BitWriter) -> rt::Result<()> {
        let mut ies: Vec<rt::ie::RawIe> = Vec::new();
        if let Some(x) = &self.mdt_configuration {
            ies.push(rt::ie::RawIe::new(255, rt::ie::Criticality::Ignore, x)?);
        }
        if let Some(x) = &self.trace_collection_entity_uri {
            ies.push(rt::ie::RawIe::new(257, rt::ie::Criticality::Ignore, x)?);
        }
        ies.extend(self.unknown_ies.iter().cloned());
        rt::ie::write_container(w, rt::Size::range(1, 65535), &ies)
    }
}

impl rt::AperDecode for TraceActivationExtIes {
    fn aper_decode(r: &mut rt::BitReader<'_>) -> rt::Result<Self> {
        let mut s_mdt_configuration: Option<MdtConfiguration> = None;
        let mut s_trace_collection_entity_uri: Option<UriAddress> = None;
        let mut unknown_ies = Vec::new();
        for ie in rt::ie::read_container(r, rt::Size::range(1, 65535))? {
            match ie.id {
                255 => rt::ie::set_once(&mut s_mdt_configuration, 255, ie.decode()?)?,
                257 => rt::ie::set_once(&mut s_trace_collection_entity_uri, 257, ie.decode()?)?,
                _ => {
                    rt::ie::note_unknown(&ie);
                    unknown_ies.push(ie)
                }
            }
        }
        Ok(Self {
            mdt_configuration: s_mdt_configuration,
            trace_collection_entity_uri: s_trace_collection_entity_uri,
            unknown_ies,
        })
    }
}

