/// ASN.1 `TraceDepth` (NGAP-IEs).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub enum TraceDepth {
    /// `minimum`
    Minimum,
    /// `medium`
    Medium,
    /// `maximum`
    Maximum,
    /// `minimumWithoutVendorSpecificExtension`
    MinimumWithoutVendorSpecificExtension,
    /// `mediumWithoutVendorSpecificExtension`
    MediumWithoutVendorSpecificExtension,
    /// `maximumWithoutVendorSpecificExtension`
    MaximumWithoutVendorSpecificExtension,
    /// `minimumOnlyVendorSpecificTraceRecord` (extension addition)
    MinimumOnlyVendorSpecificTraceRecord,
    /// `mediumOnlyVendorSpecificTraceRecord` (extension addition)
    MediumOnlyVendorSpecificTraceRecord,
    /// `maximumOnlyVendorSpecificTraceRecord` (extension addition)
    MaximumOnlyVendorSpecificTraceRecord,
}

impl rt::AperEncode for TraceDepth {
    fn aper_encode(&self, w: &mut rt::BitWriter) -> rt::Result<()> {
        let index: u64 = match self {
            Self::Minimum => 0,
            Self::Medium => 1,
            Self::Maximum => 2,
            Self::MinimumWithoutVendorSpecificExtension => 3,
            Self::MediumWithoutVendorSpecificExtension => 4,
            Self::MaximumWithoutVendorSpecificExtension => 5,
            Self::MinimumOnlyVendorSpecificTraceRecord => 6,
            Self::MediumOnlyVendorSpecificTraceRecord => 7,
            Self::MaximumOnlyVendorSpecificTraceRecord => 8,
        };
        w.write_index(index, 6, true)
    }
}

impl rt::AperDecode for TraceDepth {
    fn aper_decode(r: &mut rt::BitReader<'_>) -> rt::Result<Self> {
        Ok(match r.read_index(6, true)? {
            0 => Self::Minimum,
            1 => Self::Medium,
            2 => Self::Maximum,
            3 => Self::MinimumWithoutVendorSpecificExtension,
            4 => Self::MediumWithoutVendorSpecificExtension,
            5 => Self::MaximumWithoutVendorSpecificExtension,
            6 => Self::MinimumOnlyVendorSpecificTraceRecord,
            7 => Self::MediumOnlyVendorSpecificTraceRecord,
            8 => Self::MaximumOnlyVendorSpecificTraceRecord,
            i => return Err(r.error(rt::ErrorKind::InvalidIndex(i))),
        })
    }
}

